edits.newText:
for (const cliOption of cliOptions) {
  // Check if any alias was already parsed
  const parsedAlias = cliOption.names.find(
    (name) => parsed[name] !== undefined
  )

  if (parsedAlias !== undefined) {
    // If any alias was parsed, set all aliases to the parsed value
    for (const name of cliOption.names) {
      options[name] = parsed[parsedAlias]
    }
  } else if (!ignoreDefault && cliOption.config.default !== undefined) {
    // Otherwise, set defaults if applicable
    for (const name of cliOption.names) {
      options[name] = cliOption.config.default
    }
  }

